import numpy as np
def equation(t, x, v, params):
    w,p0,p1,A,B,A1,B1,c1,c2,c3,c4 = params[:11] if False else [params[i] for i in range(10)]+[0]
    C=np.cos(w*t); S=np.sin(w*t)
    return p0 + p1*t + (A+A1*t)*C + (B+B1*t)*S + c1*v + c2/v + c3*np.log(v) + c4*v*S + params[10]*v*C + params[11]*x**3 + params[12]*v*np.abs(v)

def dico(w):
    C=np.cos(w*t);S=np.sin(w*t)
    return {'1':np.ones_like(t),'C':C,'S':S,'t':t,'x':x,'v':v,'x3':x**3,'v|v|':v*np.abs(v),'1/v':1/v,'logv':np.log(v),
       'vS':v*S,'vC':v*C,'tC':t*C,'tS':t*S,'S/v':S/v,'C/v':C/v,'expv':np.exp(-v),'C2':np.cos(2*w*t),'S2':np.sin(2*w*t),'t2':t*t,'xS':x*S,'xC':x*C,'x2':x*x,'tanhv':np.tanh(v),'v2':v*v}
def fitset(names,ws=np.linspace(0.4,0.7,301)):
    out=[]
    for w in ws:
        D=dico(w)
        M=np.c_[tuple([D[n] for n in names])]
        c=np.linalg.lstsq(M,dv_dt,rcond=None)[0]
        out.append((np.mean((dv_dt-M@c)**2)/np.var(dv_dt),w,np.round(c,4)))
    out.sort(key=lambda z:z[0]); return out[0]
